use super::*;
use openbindings_internal_schema::{Control as InternalControl,Failure,preparation::Attempt};
use std::cell::RefCell;
use std::sync::atomic::{AtomicBool,AtomicUsize,Ordering::Relaxed};
use serde_json::json;
thread_local!{static TRACE:RefCell<Option<Vec<(&'static str,usize)>>>=const{RefCell::new(None)};}
pub(super) fn event(kind:&'static str,n:usize){TRACE.with(|t|{if let Some(v)=t.borrow_mut().as_mut(){v.push((kind,n));}})}
fn tracing(){TRACE.with(|t|*t.borrow_mut()=Some(Vec::with_capacity(128)));}
fn trace()->Vec<(&'static str,usize)>{TRACE.with(|t|t.borrow_mut().take().unwrap())}
fn old(s:&State,g:&mut Graph)->Result<State,NoVerdict>{
 debug_assert!(s.witness.is_none()||s.valid==FALSE);
 g.work(s.items.len().saturating_add(s.properties.len()).saturating_add(1))?;
 let mut bytes=256usize.saturating_add(s.items.len().saturating_mul(128));
 for name in s.properties.keys(){g.work(name.len().saturating_add(1))?;bytes=bytes.saturating_add(name.len().saturating_mul(2).saturating_add(256));}
 g.charge(bytes)?;Ok(s.clone())
}
fn copied(s:&State,g:&mut Graph,new:bool)->Result<State,NoVerdict>{if new{s.copied(g)}else{old(s,g)}}
fn same(a:&State,b:&State){assert_eq!(a.valid,b.valid);assert_eq!(a.properties,b.properties);assert_eq!(a.items,b.items);match(&a.witness,&b.witness){(Some(a),Some(b))=>assert!(Arc::ptr_eq(a,b)),(None,None)=>{},_=>panic!("witness changed")}}
fn costs(s:&State,new:bool)->(usize,usize){let bytes=if s.items.is_empty()&&s.properties.is_empty()&&new{0}else{256+s.items.len()*128+s.properties.keys().map(|n|n.len()*2+256).sum::<usize>()};let work=1+s.items.len()+s.properties.len()+s.properties.keys().map(|n|n.len()+1).sum::<usize>();(bytes,work)}
fn states()->Vec<(&'static str,State)>{let mut p=State::truth(TRUE);p.properties.insert(vec![0x61,0xd800,0x62],TRUE);let mut i=State::truth(FALSE);i.items.insert(9,FALSE);let mut b=p.clone();b.items=i.items.clone();vec![("empty",State::truth(TRUE)),("props",p),("items",i),("both",b)]}
#[test]fn sc01_exact_matrix_names_and_one_below(){
 let c=AtomicBool::new(false);let mut rows=states();let mut n=State::truth(TRUE);for name in [vec![],vec![0xdfff],vec![0xd83d,0xde00],vec![0,47,126]]{n.properties.insert(name,TRUE);}rows.push(("names",n));
 for(name,s)in rows{for new in[false,true]{let(b,w)=costs(&s,new);let mut g=Graph::new(b,Some(w),64,&c);let t=copied(&s,&mut g,new).unwrap();same(&s,&t);assert_eq!(g.remaining().bytes,0);assert_eq!(g.remaining().work,Some(0));let mut g=Graph::new(b,Some(w-1),64,&c);assert_eq!(copied(&s,&mut g,new).err().unwrap().code,"evaluation-work-limit");if b>0{let mut g=Graph::new(b-1,Some(w),64,&c);assert_eq!(copied(&s,&mut g,new).err().unwrap().code,"semantic-analysis-memory-limit");}println!("STATE_MATRIX {}",json!({"name":name,"new":new,"bytes":b,"work":w}));}}
}
struct Stop{at:usize,n:AtomicUsize}
impl Stop{fn new(at:usize)->Self{Self{at,n:AtomicUsize::new(0)}}fn poll(&self)->bool{event("poll",0);self.n.fetch_add(1,Relaxed)>=self.at}}
impl WorkControl for Stop{fn is_cancelled(&self)->bool{self.poll()}}
impl InternalControl for Stop{fn is_cancelled(&self)->bool{self.poll()}fn charge_allocation(&self,n:usize)->Result<(),Failure>{event("parent_allocation",n);InternalControl::check(self)}}
fn cancelled(x:Result<State,NoVerdict>)->String{match x{Ok(_)=>"ok".into(),Err(e)=>e.code.into_owned()}}
#[test]fn sc02_order_charge_zero_and_all_actual_stops(){
 for(name,s)in states(){let mut pair=Vec::new();let mut totals=Vec::new();for new in[false,true]{let c=Stop::new(usize::MAX);tracing();let result=Attempt::run(10000,10000,&c,|a|{let mut g=Graph::with_preparation(10000,Some(10000),64,&c,Some(a));copied(&s,&mut g,new).unwrap();a.allocated()}).unwrap();let log=trace();assert!(log.contains(&("charge",costs(&s,new).0)));assert!(log.contains(&("parent_allocation",costs(&s,new).0)));assert_eq!(result,costs(&s,new).0);pair.push(log);totals.push(c.n.load(Relaxed));}
 assert_eq!(totals[0],totals[1]);let adjusted=pair[0].iter().map(|&(k,n)|(k,if name=="empty"&&(k=="charge"||k=="parent_allocation"){0}else{n})).collect::<Vec<_>>();assert_eq!(adjusted,pair[1]);
 for at in 0..totals[0]{let mut result=Vec::new();for new in[false,true]{let c=Stop::new(at);let outer=Attempt::run(10000,10000,&c,|a|{let mut g=Graph::with_preparation(10000,Some(10000),64,&c,Some(a));cancelled(copied(&s,&mut g,new))});result.push(match outer{Ok(inner)=>inner,Err(e)=>e.code.into_owned()});}assert_eq!(result[0],result[1]);assert_eq!(result[0],"caller-cancelled");}
 println!("STATE_TRACE {}",json!({"name":name,"before":pair[0],"after":pair[1],"stops":totals[0]}));}
}
fn allocated(s:&State,g:&mut Graph,new:bool,repeats:usize)->serde_json::Value{let start=crate::review_allocations::start();for _ in 0..repeats{let t=copied(s,g,new).unwrap();assert_eq!(s.valid,t.valid);if let Some(w)=&s.witness{assert!(Arc::ptr_eq(w,t.witness.as_ref().unwrap()));}std::hint::black_box(&t);drop(t);}crate::review_allocations::finish(start,repeats)}
#[test]fn sc03_empty_zero_requests_constant_symbolic_witness_and_removed_nodes(){
 let c=AtomicBool::new(false);let mut arena=Graph::new(usize::MAX,None,64,&c);let(_,formula)=arena.variable(decision::Class::External).unwrap();
 for valid in[TRUE,FALSE,formula]{for witness in[false,true]{if witness&&valid!=FALSE{continue;}for cleared in[0,1,2]{let mut s=State::truth(valid);if witness{s.witness=Some(explain::review_seed());}if cleared!=0{for n in 0..32{s.properties.insert(vec![n],formula);s.items.insert(n as usize,formula);}if cleared==1{s.properties.clear();s.items.clear();}else{for n in 0..32{s.properties.remove(&vec![n]);s.items.remove(&(n as usize));}}}assert!(s.properties.is_empty()&&s.items.is_empty());for new in[false,true]{for repeats in[1,1000]{let m=allocated(&s,&mut arena,new,repeats);assert_eq!(m["allocations_per_op"],json!(0.0));assert_eq!(m["requested_bytes_per_op"],json!(0.0));assert_eq!(m["baseline_live_bytes"],m["ending_live_bytes"]);if let Some(w)=&s.witness{assert_eq!(Arc::strong_count(w),1);}println!("STATE_ALLOC {}",json!({"kind":"empty","formula":valid,"witness":witness,"emptied":cleared,"new":new,"repeats":repeats,"metrics":m}));}}}}}
}
#[test]fn sc04_nonempty_allocation_requests_and_ownership_unchanged(){let c=AtomicBool::new(false);for width in[1,12,64]{for which in[1,2,3]{for witness in[false,true]{let mut s=State::truth(if witness{FALSE}else{TRUE});if witness{s.witness=Some(explain::review_seed());}for n in 0..width{if which&1!=0{s.properties.insert(vec![n as u16,0xd800,0xd83d,0xde00],TRUE);}if which&2!=0{s.items.insert(n,FALSE);}}let mut results=Vec::new();for new in[false,true]{let mut g=Graph::new(usize::MAX,None,64,&c);let m=allocated(&s,&mut g,new,3);assert_eq!(m["baseline_live_bytes"],m["ending_live_bytes"]);results.push(m);}for key in["allocations_per_op","requested_bytes_per_op","incremental_peak_bytes"]{assert_eq!(results[0][key],results[1][key]);}assert_eq!(costs(&s,false),costs(&s,true));println!("STATE_ALLOC {}",json!({"kind":"nonempty","width":width,"maps":which,"witness":witness,"before":results[0],"after":results[1]}));}}}}
#[test]fn sc05_seed_and_symbolic_identity_survive_clones_then_drop(){let c=AtomicBool::new(false);let mut g=Graph::new(100000,None,64,&c);let(v,f)=g.variable(decision::Class::External).unwrap();let t=State::truth(f);let copied=t.copied(&mut g).unwrap();assert_eq!(g.support(copied.valid).unwrap(),vec![v]);let mut s=State::truth(FALSE);let owner=explain::review_seed();let weak=Arc::downgrade(&owner);s.witness=Some(owner.clone());drop(owner);{let t=s.copied(&mut g).unwrap();same(&s,&t);assert_eq!(weak.strong_count(),2);}assert_eq!(weak.strong_count(),1);drop(s);assert!(weak.upgrade().is_none());}
#[test]fn sc06_actual_nested_prior_causes_zero_remaining_and_overflow(){
 let s=State::truth(TRUE);let c=AtomicBool::new(false);
 for cause in["work","allocation","child-work","child-allocation","overflow","cancel"]{let cancel=AtomicBool::new(false);let result=Attempt::run(1000,usize::MAX,&cancel,|outer|{
 let expected=match cause{"work"=>{assert!(outer.charge_work(usize::MAX).is_err());"preparation-sdk-work-units"},"allocation"=>{outer.allocation_limit_reached();"preparation-sdk-reservation-bytes"},"child-work"=>{assert!(Attempt::run(0,100,outer,|child|child.charge_work(1)).is_err());"preparation-sdk-work-units"},"child-allocation"=>{assert!(Attempt::run(100,0,outer,|child|child.charge_allocation(1)).is_err());"preparation-sdk-reservation-bytes"},"overflow"=>{outer.charge_allocation(usize::MAX).unwrap();assert!(outer.charge_allocation(1).is_err());"preparation-sdk-reservation-bytes"},_=>{cancel.store(true,Relaxed);"caller-cancelled"}};
 let mut g=Graph::with_preparation(0,Some(1),64,&cancel,Some(outer));assert_eq!(s.copied(&mut g).err().unwrap().code,expected);expected});assert_eq!(result.err().unwrap().code,match cause{"work"|"child-work"=>"preparation-sdk-work-units","cancel"=>"caller-cancelled",_=>"preparation-sdk-reservation-bytes"});}
 Attempt::run(100,0,&c,|a|{let mut g=Graph::with_preparation(0,Some(1),64,&c,Some(a));s.copied(&mut g).unwrap();assert_eq!(a.allocated(),0);}).unwrap();
 Attempt::run(100,10,&c,|a|{a.charge_allocation(10).unwrap();let mut g=Graph::with_preparation(0,Some(1),64,&c,Some(a));s.copied(&mut g).unwrap();assert_eq!(a.allocated(),10);}).unwrap();
}
#[test]fn sc07_graph_prespend_checked_add_and_work_boundary(){let c=AtomicBool::new(false);let empty=State::truth(TRUE);let mut g=Graph::new(usize::MAX,None,64,&c);g.charge(usize::MAX).unwrap();empty.copied(&mut g).unwrap();assert_eq!(g.remaining().bytes,0);let mut s=State::truth(TRUE);s.items.insert(0,TRUE);assert_eq!(s.copied(&mut g).err().unwrap().code,"semantic-analysis-memory-limit");let mut g=Graph::new(0,Some(0),64,&c);assert_eq!(empty.copied(&mut g).err().unwrap().code,"evaluation-work-limit");let mut g=Graph::new(0,None,64,&c);g.work(usize::MAX).unwrap();assert_eq!(empty.copied(&mut g).err().unwrap().code,"evaluation-work-limit");}
#[test]fn sc08_exact_preserved_64k_benchmark_request(){let r:serde_json::Value=serde_json::from_str(include_str!("64k-request.json")).unwrap();assert_eq!(r["limits"]["program_bytes"],65536);assert_eq!(r["expected"]["status"],"satisfies");let supplied=serde_json::from_value(r["resources"].clone()).unwrap();let limits=serde_json::from_value(r["limits"].clone()).unwrap();let context=crate::review_benchmark::context(r["schema"].as_str().unwrap(),&supplied,&limits,false);let p=context.prepare_input();assert!(p.is_ready());let value=crate::review_benchmark::parse_value(r["value"].as_str().unwrap());for _ in 0..3{let o=p.validate(&value,false).observation();assert_eq!(o,r["expected"]);println!("EXACT_64K {}",o);}}
#[test]fn sc09_global_copy_layout_and_no_new_owners(){assert_eq!(size_of::<State>(),64);assert_eq!(size_of::<readings::Fields>(),8);assert_eq!(execution::review_frame_size(),256);println!("STATE_LAYOUT {}",json!({"state":size_of::<State>(),"run":size_of::<Run>(),"frame":execution::review_frame_size(),"fields":size_of::<readings::Fields>()}));}
